
import * as DB from './db.js'; import {analyzePdf,textToBlocks} from './pdf-basic.js'; import {makeZip,readZip} from './zip-lite.js';
const APP_VERSION='FINAL CONSOLIDATED · 2026.09.13';
const app=document.querySelector('#app'),toastEl=document.querySelector('#toast'),picker=document.querySelector('#file-picker');
let state={route:'library',params:{},courses:[],lessons:[],topics:[],documents:[],pdfSources:[],sourceAnchors:[],recent:[],settings:{theme:'Midnight Violet',mode:'dark',readerTheme:'follow',fontSize:17,lineHeight:1.72,width:'72ch',reducedMotion:false,uiDensity:'comfortable',cardRadius:20,glow:1},dirty:false,searchResults:[]};
const THEME_NAMES=['Midnight Violet','Obsidian','Deep Ocean','Emerald','Crimson','Royal Gold','Arctic','Cyber Glass','Cosmos','Aurora','Paper','Ivory','Sepia Scholar','Nordic','Sakura','Forest','Graphite','Monochrome','Amethyst','Celestial'];
const THEMES={
'Midnight Violet':['#08101d','#10192a','#15213a','#eef3ff','#8fa0bd','#8d65ff','#4ec7ff'],Obsidian:['#050607','#101113','#181a1e','#f2f2f2','#9b9da3','#b8beca','#7e8796'],'Deep Ocean':['#04121d','#0a2130','#103248','#e9f8ff','#8fb7c7','#1fa7d8','#55e0ff'],Emerald:['#071712','#10251d','#17362a','#effff7','#97b8a8','#34c987','#7cf0b9'],Crimson:['#17070b','#271016','#39141d','#fff1f3','#c39aa1','#e54963','#ff8798'],'Royal Gold':['#141109','#231d10','#362d17','#fff8e7','#b8a98b','#d5ad46','#ffe08a'],Arctic:['#07131d','#102536','#17344a','#f3fbff','#9bb5c7','#68c7ff','#b6efff'],'Cyber Glass':['#050916','#0d1730','#12234a','#f2f7ff','#8fa6c8','#00d6ff','#a56cff'],Cosmos:['#080816','#14142d','#1d1a43','#f5f1ff','#a09abc','#7758ff','#d25dff'],Aurora:['#071515','#102c2a','#193945','#f0fffb','#91b8b5','#39d3b0','#a06dff'],Paper:['#17140f','#262119','#342d23','#fff9ed','#c0b5a5','#c49a62','#e4bd7d'],Ivory:['#17120d','#281f17','#3a2f23','#fff8eb','#bba997','#c49365','#e2ba8e'],'Sepia Scholar':['#17100b','#2b1d13','#3b2a1b','#fff3dc','#c2ab8f','#b67d47','#e2b879'],Nordic:['#0c1115','#192229','#23313a','#f6fbff','#a0afb8','#8fb8d0','#d2e7f0'],Sakura:['#160d12','#291722','#3b2030','#fff3f8','#c0a1ad','#e47ba5','#ffb7d2'],Forest:['#08130d','#14251a','#203827','#f2fff6','#98b2a0','#4eaa68','#9bcf7b'],Graphite:['#0b0d10','#181b20','#24282f','#f5f7fa','#9ea4ad','#6f89aa','#a9b8c9'],Monochrome:['#000','#111','#1d1d1d','#fff','#aaa','#fff','#777'],Amethyst:['#12091a','#24132f','#351b47','#fbf2ff','#b8a0c5','#ad65e8','#e59cff'],Celestial:['#07101f','#111f36','#19304f','#f3f8ff','#9babc1','#6aa8ff','#c1d7ff']};
function toast(s){toastEl.textContent=s;toastEl.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>toastEl.classList.remove('show'),2300)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtDate(n){return new Date(n).toLocaleDateString('ru-RU',{day:'2-digit',month:'short',year:'numeric'})}
async function load(){state.courses=await DB.all('courses');state.lessons=await DB.all('lessons');state.topics=await DB.all('topics');state.documents=await DB.all('documents');state.pdfSources=await DB.all('pdfSources');state.sourceAnchors=await DB.all('sourceAnchors');state.recent=await DB.all('recent');state.settings={...state.settings,...await DB.setting('appearance',{})};applyTheme();parseRoute();setupSW();render()}
function applyTheme(){const t=THEMES[state.settings.theme]||THEMES['Midnight Violet'];let [bg,s1,s2,text,muted,a1,a2]=t;let mode=state.settings.mode;if(mode==='system')mode=matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light';if(mode==='light'){const warm=/Paper|Ivory|Sepia|Royal Gold|Sakura/.test(state.settings.theme);[bg,s1,s2,text,muted]=warm?['#f7f1e6','#fffdf8','#eee5d6','#201c18','#746b61']:['#f3f6fb','#ffffff','#e9eef7','#172034','#647089'];a1=t[5];a2=t[6]}let readerBg=bg,readerCard=s1,readerText=text;if(state.settings.readerTheme==='paper'){readerBg='#ece3d2';readerCard='#fffaf0';readerText='#2a241d'}else if(state.settings.readerTheme==='sepia'){readerBg='#d9c7aa';readerCard='#f3e6cf';readerText='#35291f'}else if(state.settings.readerTheme==='oled'){readerBg='#000';readerCard='#050505';readerText='#f5f5f5'}const r=document.documentElement.style;r.setProperty('--app-bg',bg);r.setProperty('--surface',s1);r.setProperty('--surface2',s2);r.setProperty('--glass',s1+'dd');r.setProperty('--text',text);r.setProperty('--muted',muted);r.setProperty('--accent',a1);r.setProperty('--accent2',a2);r.setProperty('--reader-bg',readerBg);r.setProperty('--reader-card',readerCard);r.setProperty('--reader-text',readerText);r.setProperty('--font-size',state.settings.fontSize+'px');r.setProperty('--line-height',state.settings.lineHeight);r.setProperty('--reader-width',state.settings.width);r.setProperty('--card-radius',(state.settings.cardRadius||20)+'px');r.setProperty('--theme-glow',String(state.settings.glow??1));r.setProperty('--ui-density',state.settings.uiDensity==='compact'?'.86':state.settings.uiDensity==='spacious'?'1.12':'1');document.body.classList.toggle('reduce-motion',!!state.settings.reducedMotion);document.documentElement.dataset.theme=state.settings.theme.toLowerCase().replace(/[^a-z0-9]+/g,'-');document.documentElement.dataset.mode=mode}
function parseRoute(){const h=location.hash.slice(1)||'/library';const p=h.split('/').filter(Boolean);state.route=p[0]||'library';state.params={id:p[1],sub:p[2]}}
addEventListener('hashchange',()=>{parseRoute();render()});
function go(path){location.hash=path}
function iconFor(c){return c.icon||'◈'}
function hashText(s=''){let h=2166136261;for(const ch of String(s)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return Math.abs(h>>>0)}
function artKind(title='',index=0){const t=String(title).toLowerCase();if(/defi|eth|block|crypto|крип|блокчейн/.test(t))return'orbit';if(/math|матем|анализ|алгеб|геом/.test(t))return'wave';if(/эконом|finance|финанс|рынок/.test(t))return'bars';if(/програм|code|javascript|python|dev/.test(t))return'code';if(/англ|english|язык|ling/.test(t))return'mountain';return['orbit','wave','bars','code','mountain','crystal'][(hashText(title)+index)%6]}
function artSvg(title='',index=0,wide=false){const k=artKind(title,index),id='g'+((hashText(title)+index)%997),v=wide?'0 0 900 320':'0 0 560 300';const common=`<defs><linearGradient id="${id}a" x1="0" x2="1"><stop stop-color="var(--accent)" stop-opacity=".9"/><stop offset="1" stop-color="var(--accent2)" stop-opacity=".75"/></linearGradient><radialGradient id="${id}r"><stop stop-color="var(--accent2)" stop-opacity=".55"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></radialGradient><filter id="${id}b"><feGaussianBlur stdDeviation="12"/></filter></defs>`;let art='';if(k==='orbit')art=`<circle cx="390" cy="120" r="128" fill="url(#${id}r)"/><circle cx="390" cy="120" r="72" fill="none" stroke="url(#${id}a)" stroke-width="2"/><ellipse cx="390" cy="120" rx="150" ry="48" fill="none" stroke="var(--accent2)" stroke-opacity=".5" transform="rotate(-18 390 120)"/><circle cx="496" cy="68" r="12" fill="var(--accent2)"/><circle cx="335" cy="160" r="5" fill="var(--accent)"/><path d="M250 255 C320 188 410 195 550 120" fill="none" stroke="url(#${id}a)" stroke-width="3" opacity=".45"/>`;else if(k==='wave')art=`<path d="M0 220 C65 90 120 245 185 128 S305 42 360 150 S470 260 560 100" fill="none" stroke="url(#${id}a)" stroke-width="4"/><path d="M0 245 C65 115 120 270 185 153 S305 67 360 175 S470 285 560 125" fill="none" stroke="var(--accent2)" stroke-opacity=".24" stroke-width="2"/><g opacity=".18" stroke="var(--accent2)">${Array.from({length:12},(_,i)=>`<line x1="${i*50}" y1="30" x2="${i*50}" y2="280"/>`).join('')}</g>`;else if(k==='bars')art=`<g transform="translate(250 42)"><rect x="0" y="150" width="42" height="95" rx="8" fill="var(--accent)" opacity=".42"/><rect x="58" y="95" width="42" height="150" rx="8" fill="var(--accent2)" opacity=".55"/><rect x="116" y="35" width="42" height="210" rx="8" fill="url(#${id}a)"/><rect x="174" y="118" width="42" height="127" rx="8" fill="var(--accent)" opacity=".55"/><path d="M-15 160 L70 112 L130 58 L192 120" fill="none" stroke="white" stroke-opacity=".75" stroke-width="3"/></g>`;else if(k==='code')art=`<rect x="245" y="52" width="272" height="196" rx="22" fill="rgba(3,8,18,.52)" stroke="var(--accent2)" stroke-opacity=".4"/><circle cx="272" cy="79" r="6" fill="#ff6b7d"/><circle cx="292" cy="79" r="6" fill="#ffd166"/><circle cx="312" cy="79" r="6" fill="#5fe0aa"/><g stroke="url(#${id}a)" stroke-width="7" stroke-linecap="round"><path d="M282 120h74"/><path d="M282 145h128"/><path d="M310 170h150"/><path d="M282 195h98"/><path d="M328 220h116"/></g>`;else if(k==='mountain')art=`<circle cx="438" cy="83" r="48" fill="url(#${id}r)"/><path d="M150 270 L282 105 L356 198 L421 132 L560 270 Z" fill="url(#${id}a)" opacity=".5"/><path d="M150 270 L282 105 L356 198 L421 132 L560 270" fill="none" stroke="var(--accent2)" stroke-opacity=".55" stroke-width="2"/><path d="M276 112l20 52 23-20" fill="none" stroke="white" stroke-opacity=".7" stroke-width="3"/>`;else art=`<g transform="translate(390 150)"><path d="M0-96 L82-28 L52 82 L-52 82 L-82-28Z" fill="url(#${id}a)" opacity=".5"/><path d="M0-96 L0 18 L82-28 M0 18 L52 82 M0 18 L-52 82 M0 18 L-82-28" fill="none" stroke="white" stroke-opacity=".55" stroke-width="2"/><circle r="122" fill="none" stroke="var(--accent2)" stroke-opacity=".22"/></g>`;return `<svg class="art-svg" viewBox="${v}" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${common}<rect width="100%" height="100%" fill="transparent"/>${art}</svg>`}
function navIcon(name){const icons={library:'<path d="M4 5.5 12 2l8 3.5v13L12 22 4 18.5z"/><path d="M12 2v20M4 5.5l8 4 8-4"/>',search:'<circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 5 5"/>',favorites:'<path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1L3.2 9.4l6.1-.9z"/>',recent:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.5 2"/>',pdf:'<path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5M9 15h6M9 18h4"/>',trash:'<path d="M5 7h14M9 7V4h6v3M7 7l1 14h8l1-14"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.5-2-3.4-2.4 1A8 8 0 0 0 15 6l-.3-2.6h-4L10.3 6a8 8 0 0 0-1.5.9l-2.4-1-2 3.4 2 1.5a7 7 0 0 0 0 2.1l-2 1.5 2 3.4 2.4-1a8 8 0 0 0 1.5.9l.4 2.6h4l.3-2.6a8 8 0 0 0 1.5-.9l2.4 1 2-3.4-2-1.5c.1-.3.1-.7.1-1z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.library}</svg>`}
function nav(){const items=[['library','Библиотека'],['search','Поиск'],['favorites','Избранное'],['recent','Недавние'],['pdf','PDF'],['trash','Корзина']];return `<aside class="rail"><div class="brand"><div class="logo"><span>K</span></div><div class="brand-copy"><b>Knowledge</b><small>Studio</small></div></div><div class="rail-label">НАВИГАЦИЯ</div>${items.map(([r,t])=>`<button class="navbtn ${state.route===r?'active':''}" data-go="/${r}" title="${t}">${navIcon(r)}<span>${t}</span></button>`).join('')}<div class="nav-spacer"></div><div class="rail-label">СИСТЕМА</div><button class="navbtn ${state.route==='settings'?'active':''}" data-go="/settings" title="Настройки">${navIcon('settings')}<span>Настройки</span></button></aside>`}
function topbar(title,crumbs='',actions=''){return `<header class="topbar"><div><div class="titlebar">${esc(title)}</div><div class="crumbs">${crumbs}</div></div><div class="top-actions">${actions}</div></header>`}
function shell(title,crumbs,body,actions=''){return `<div class="app-shell">${nav()}<main class="workspace">${topbar(title,crumbs,actions)}<section class="content">${body}</section></main></div>`}
function countChildren(courseId){const ls=state.lessons.filter(x=>x.courseId===courseId&&!x.deletedAt);const ids=new Set(ls.map(x=>x.id));return {lessons:ls.length,topics:state.topics.filter(x=>ids.has(x.lessonId)&&!x.deletedAt).length}}
function renderLibrary(){const cs=state.courses.filter(x=>!x.deletedAt).sort((a,b)=>(a.sortKey||'').localeCompare(b.sortKey||''));const topicCount=state.topics.filter(x=>!x.deletedAt).length,lessonCount=state.lessons.filter(x=>!x.deletedAt).length;const hero=`<section class="library-hero"><div class="hero-copy"><span class="eyebrow"><i></i> LOCAL-FIRST · OFFLINE</span><h1>Ваше пространство<br><em>для глубоких знаний</em></h1><p>Курсы, конспекты, PDF и учебные материалы — в одной красивой системе, которая работает локально на вашем устройстве.</p><div class="hero-actions"><button class="btn primary btn-lg" data-action="new-course">+ Создать курс</button><button class="btn glass btn-lg" data-go="/pdf">Импортировать PDF</button></div><div class="hero-metrics"><div><b>${cs.length}</b><span>курсов</span></div><div><b>${lessonCount}</b><span>уроков</span></div><div><b>${topicCount}</b><span>тем</span></div></div></div><div class="hero-art"><div class="orb orb-a"></div><div class="orb orb-b"></div><div class="knowledge-core"><div class="core-ring r1"></div><div class="core-ring r2"></div><div class="core-ring r3"></div><div class="core-gem">K</div>${[0,1,2,3,4,5].map(i=>`<span class="spark s${i}"></span>`).join('')}</div><div class="floating-card fc1"><span>◆</span><b>IDEA</b></div><div class="floating-card fc2"><span>∑</span><b>FORMULA</b></div><div class="floating-card fc3"><span>⌘</span><b>CODE</b></div></div></section>`;let courses;if(cs.length){courses=`<div class="course-grid">${cs.map((c,i)=>{const n=countChildren(c.id);return `<article class="course-card"><div class="course-cover">${artSvg(c.title,i)}<div class="cover-shade"></div><div class="course-badge">${iconFor(c)}</div><button class="course-menu" data-action="edit-course" data-id="${c.id}" aria-label="Настройки курса">•••</button></div><div class="course-info"><div><h3>${esc(c.title)}</h3><p>${esc(c.description||'Личный учебный курс')}</p></div><div class="course-meta"><span>${n.lessons} уроков</span><i></i><span>${n.topics} тем</span><button class="round-arrow course-open" data-go="/course/${c.id}" aria-label="Открыть курс">→</button></div></div></article>`}).join('')}</div>`}else{courses=`<div class="empty-premium"><div class="empty-copy"><span class="eyebrow"><i></i> НОВАЯ БИБЛИОТЕКА</span><h2>Начните с первого курса</h2><p>Создайте свою структуру знаний или импортируйте PDF. Оформление курса появится автоматически и будет адаптироваться к выбранной теме.</p><button class="btn primary btn-lg" data-action="new-course">Создать первый курс</button></div><div class="preview-stack">${['DeFi','Математика','Экономика','Программирование'].map((x,i)=>`<div class="mini-preview p${i}">${artSvg(x,i)}<strong>${x}</strong><span>${['Протоколы · Ethereum','Анализ · Формулы','Рынки · Макро','Код · Архитектура'][i]}</span></div>`).join('')}</div></div>`}const body=`${hero}<div class="section-head premium-head"><div><span class="section-kicker">ВАША КОЛЛЕКЦИЯ</span><h2>Курсы</h2></div><div class="spacer"></div><button class="btn glass" data-go="/search">⌕ Поиск</button><button class="btn primary" data-action="new-course">+ Новый курс</button></div>${courses}`;return shell('Библиотека','Главная',body,`<button class="btn glass hide-phone" data-go="/pdf">Импорт PDF</button>`) }
function renderCourse(id){const c=state.courses.find(x=>x.id===id);if(!c)return notFound();const ls=state.lessons.filter(x=>x.courseId===id&&!x.deletedAt).sort(sorter);const count=countChildren(id);const body=`<section class="course-hero"><div class="course-hero-copy"><span class="eyebrow"><i></i> КУРС</span><h1>${esc(c.title)}</h1><p>${esc(c.description||'Добавьте описание курса в настройках.')}</p><div class="hero-metrics compact"><div><b>${count.lessons}</b><span>уроков</span></div><div><b>${count.topics}</b><span>тем</span></div></div></div><div class="course-hero-art">${artSvg(c.title,0,true)}<div class="cover-shade"></div></div></section><div class="section-head premium-head"><div><span class="section-kicker">СТРУКТУРА КУРСА</span><h2>Уроки</h2></div><div class="spacer"></div><button class="btn glass" data-action="edit-course" data-id="${c.id}">Настройки</button><button class="btn primary" data-action="new-lesson" data-id="${c.id}">+ Новый урок</button></div>${ls.length?`<div class="lesson-grid">${ls.map((l,i)=>{const n=state.topics.filter(x=>x.lessonId===l.id&&!x.deletedAt).length;return `<article class="lesson-card" draggable="true" data-drag="lesson" data-id="${l.id}"><div class="lesson-visual">${artSvg(l.title,i)}<span class="lesson-number">${String(i+1).padStart(2,'0')}</span></div><div class="lesson-card-body"><span class="lesson-kicker">УРОК ${i+1}</span><h3>${esc(l.title)}</h3><p>${esc(l.description||'Структурированный учебный материал')}</p><div class="lesson-foot"><span>${n} тем</span><button class="round-arrow" data-go="/lesson/${l.id}">→</button><button class="dots" data-action="edit-lesson" data-id="${l.id}">•••</button></div></div></article>`}).join('')}</div>`:`<div class="empty-premium small"><div class="empty-copy"><h2>Пока нет уроков</h2><p>Создайте первый урок и начните строить структуру курса.</p><button class="btn primary" data-action="new-lesson" data-id="${c.id}">+ Создать урок</button></div></div>`}`;return shell(c.title,`Библиотека › ${esc(c.title)}`,body,`<button class="btn glass" data-go="/library">← Библиотека</button>`) }
function renderLesson(id){const l=state.lessons.find(x=>x.id===id),c=l&&state.courses.find(x=>x.id===l.courseId);if(!l||!c)return notFound();const ts=state.topics.filter(x=>x.lessonId===id&&!x.deletedAt).sort(sorter);const body=`<section class="lesson-hero"><div><span class="eyebrow"><i></i> ${esc(c.title)}</span><h1>${esc(l.title)}</h1><p>${esc(l.description||'Все темы урока в одном месте. Читайте, редактируйте и связывайте материалы.')}</p></div><div class="lesson-hero-art">${artSvg(l.title,1,true)}</div></section><div class="section-head premium-head"><div><span class="section-kicker">СОДЕРЖАНИЕ УРОКА</span><h2>${ts.length} ${ts.length===1?'тема':'тем'}</h2></div><div class="spacer"></div><button class="btn glass" data-action="edit-lesson" data-id="${l.id}">Настройки</button><button class="btn primary" data-action="new-topic" data-id="${l.id}">+ Новая тема</button></div>${ts.length?`<div class="topic-list-premium">${ts.map((t,i)=>{const d=state.documents.find(x=>x.id===t.documentId);const blocks=d?.blocks?.length||0;return `<article class="topic-row-premium" draggable="true" data-drag="topic" data-id="${t.id}"><div class="topic-index">${String(i+1).padStart(2,'0')}</div><div class="topic-icon tone${i%5}">${['◇','⌘','∑','▦','✦'][i%5]}</div><div class="topic-main"><h3>${esc(t.title)}</h3><p>${esc(t.subtitle||'Учебная тема')}</p></div><div class="topic-stats"><span>${blocks} блоков</span>${t.favorite?'<b>★</b>':''}</div><button class="round-arrow" data-go="/topic/${t.id}">→</button><button class="dots" data-action="topic-menu" data-id="${t.id}">•••</button></article>`}).join('')}</div>`:`<div class="empty-premium small"><div class="empty-copy"><h2>Пока нет тем</h2><p>Добавьте первую тему — она получит полноценную страницу чтения и редактирования.</p><button class="btn primary" data-action="new-topic" data-id="${l.id}">+ Создать тему</button></div></div>`}`;return shell(l.title,`Библиотека › ${esc(c.title)} › ${esc(l.title)}`,body,`<button class="btn glass" data-go="/course/${c.id}">← К курсу</button>`) }
function blockHtml(b){const txt=esc(b.text||'');if(b.type==='heading')return `<h2 id="b-${b.id}">${txt}</h2>`;if(b.type==='heading3')return `<h3 id="b-${b.id}">${txt}</h3>`;if(b.type==='quote')return `<blockquote id="b-${b.id}">${txt}</blockquote>`;if(b.type==='bullet')return `<ul id="b-${b.id}"><li>${txt}</li></ul>`;if(b.type==='code')return `<pre class="codeblock" id="b-${b.id}">${txt}</pre>`;if(b.type==='math')return `<div class="mathblock" id="b-${b.id}">${txt}</div>`;if(b.type==='divider')return `<hr id="b-${b.id}">`;if(b.type==='image')return `<figure id="b-${b.id}"><img src="${esc(b.src||'')}" alt="${esc(b.alt||'')}"><figcaption class="muted">${txt}</figcaption></figure>`;if(b.type==='table'){const rows=(b.rows||[['',''],['','']]);return `<div class="table-wrap"><table id="b-${b.id}">${rows.map((r,i)=>`<tr>${r.map(c=>i===0?`<th>${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table></div>`}if(b.type==='pdfFragment')return `<div class="callout" id="b-${b.id}" data-kind="note"><div class="callout-title">PDF Fragment · стр. ${(b.source?.pageIndex??0)+1}</div><div>${txt||'Фрагмент сохранён в оригинальном PDF.'}</div><button class="btn" data-action="source" data-source="${b.source?.sourceId||''}" data-page="${b.source?.pageIndex||0}">Показать источник</button></div>`;if(b.type==='callout')return `<div class="callout" id="b-${b.id}" data-kind="${esc(b.kind||'note')}"><div class="callout-title">${calloutName(b.kind)}</div><div>${txt}</div>${b.source?`<button class="btn" data-action="source" data-source="${b.source.sourceId}" data-page="${b.source.pageIndex||0}">Источник</button>`:''}</div>`;return `<p id="b-${b.id}">${txt}${b.source?` <button class="btn" style="padding:3px 6px;font-size:11px" data-action="source" data-source="${b.source.sourceId}" data-page="${b.source.pageIndex||0}">стр. ${(b.source.pageIndex||0)+1}</button>`:''}</p>`}
function calloutName(k){return ({definition:'Определение',keyIdea:'Ключевая идея',important:'Важно',example:'Пример',note:'Примечание',question:'Вопрос',warning:'Предупреждение'})[k]||'Блок'}
function renderTopic(id){const t=state.topics.find(x=>x.id===id);if(!t)return notFound();const l=state.lessons.find(x=>x.id===t.lessonId),c=l&&state.courses.find(x=>x.id===l.courseId),d=state.documents.find(x=>x.id===t.documentId);touchRecent(t);const blocks=d?.blocks||[];const toc=blocks.filter(b=>b.type==='heading'||b.type==='heading3');const body=`<div class="topic-layout"><article class="reader"><div class="reader-inner"><span class="chip">${esc(c?.title||'')} · ${esc(l?.title||'')}</span><h1>${esc(t.title)}</h1>${t.subtitle?`<p class="muted">${esc(t.subtitle)}</p>`:''}${blocks.length?blocks.map(blockHtml).join(''):`<div class="empty">Тема пока пустая. Перейдите в режим редактирования.</div>`}</div></article><aside class="toc"><h3>Содержание</h3>${toc.length?toc.map(b=>`<a href="#b-${b.id}" data-scroll="b-${b.id}">${esc(b.text)}</a>`).join(''):'<span class="muted">Добавьте заголовки.</span>'}</aside></div>`;return shell(t.title,`${esc(c?.title)} › ${esc(l?.title)} › ${esc(t.title)}`,body,`<button class="btn" data-action="favorite" data-id="${t.id}">${t.favorite?'★':'☆'}</button><button class="btn" data-action="focus">Фокус</button><button class="btn primary" data-go="/edit/${t.id}">Редактировать</button>`) }
function renderEditor(id){const t=state.topics.find(x=>x.id===id);if(!t)return notFound();const d=state.documents.find(x=>x.id===t.documentId)||{id:t.documentId,topicId:t.id,blocks:[],revision:0};const blocks=d.blocks||[];const body=`<div class="editor-shell"><div class="editor-toolbar">${[['paragraph','¶'],['heading','H2'],['heading3','H3'],['callout:definition','Опред.'],['callout:keyIdea','Идея'],['callout:important','Важно'],['callout:example','Пример'],['callout:note','Заметка'],['callout:warning','Риск'],['callout:question','Вопрос'],['quote','❝'],['bullet','• Список'],['code','</>'],['math','∑'],['table','Таблица'],['image','Изображение'],['divider','—']].map(([k,n])=>`<button class="btn" data-addtype="${k}">${n}</button>`).join('')}<span class="spacer"></span><span id="save-state" class="badge">Сохранено</span></div><input class="editor-title" id="topic-title" value="${esc(t.title)}" aria-label="Название темы"> <div class="blocks" id="blocks">${blocks.map(editorBlock).join('')}</div><button class="add-block" data-addtype="paragraph">+ Добавить блок</button></div>`;return shell('Редактор',t.title,body,`<button class="btn" data-action="save-now">Сохранить</button><button class="btn primary" data-go="/topic/${t.id}">Готово</button>`) }
function editorBlock(b){const typ=b.type==='callout'?`${calloutName(b.kind)}`:b.type;let ctl;if(b.type==='table'){ctl=`<textarea class="block-input" data-field="rows" placeholder="Строки таблицы: значения через |">${esc((b.rows||[]).map(r=>r.join(' | ')).join('\n'))}</textarea>`}else if(b.type==='divider'){ctl=`<div class="muted">Разделитель</div>`}else if(b.type==='image'){ctl=`<div class="image-editor-preview">${b.src?`<img src="${esc(b.src)}" alt="">`:'<span>Изображение не выбрано</span>'}</div><button class="btn" type="button" data-pickimage="${b.id}">Выбрать изображение</button><input class="block-input" data-field="src" value="${esc(b.src||'')}" placeholder="Или вставьте data:image / URL"><input class="block-input" data-field="text" value="${esc(b.text||'')}" placeholder="Подпись">`}else ctl=`<textarea class="block-input ${b.type==='callout'?'editor-callout':''}" data-field="text" placeholder="Введите текст…">${esc(b.text||'')}</textarea>`;return `<div class="block" draggable="true" data-block="${b.id}"><button class="block-handle" title="Перетащить">☷</button><div><div class="block-type">${esc(typ)}</div>${ctl}</div><button class="block-delete" data-delblock="${b.id}" title="Удалить">×</button></div>`}
function renderSearch(){return shell('Поиск','По всей библиотеке',`<div class="searchbox"><input id="search-input" class="input" placeholder="Найти текст, тему, курс…"><button class="btn primary" data-action="search">Найти</button></div><div id="search-results" class="search-results">${searchResultsHtml()}</div>`) }
function searchResultsHtml(){return state.searchResults.length?state.searchResults.map(r=>`<div class="search-hit"><div class="row-title">${esc(r.title)}</div><div class="row-sub">${esc(r.course)} · ${esc(r.lesson)}</div><p>${esc(r.snippet||'')}</p><button class="btn" data-go="/topic/${r.id}">Открыть</button></div>`).join(''):`<div class="empty">Введите запрос. Поиск работает локально и offline.</div>`}
function renderPdf(){return shell('Импорт PDF','Локально · без AI',`<div class="pdf-drop" id="pdf-drop"><div class="big">⇧</div><h2>Импортировать PDF</h2><p class="muted">Оригинал будет сохранён локально. Текст извлекается без AI и не переписывается.</p><button class="btn primary" data-action="pick-pdf">Выбрать PDF</button></div><div id="pdf-progress" class="panel hidden" style="margin-top:16px"><h3 id="pdf-name">Анализ PDF</h3><div class="progress"><span id="pdf-bar"></span></div><p id="pdf-status" class="muted">Подготовка…</p></div><div class="warnbox" style="margin-top:16px"><b>PDF.js работает полностью локально:</b> оригинал сохраняется, текст и координаты извлекаются без AI. Заголовки, списки и колонки восстанавливаются эвристически; формулы, необычная вёрстка и сканы могут потребовать ручной проверки.</div>`) }
function renderSimpleList(kind){let items=[];if(kind==='favorites')items=state.topics.filter(x=>x.favorite&&!x.deletedAt);else if(kind==='recent'){const ids=state.recent.sort((a,b)=>b.openedAt-a.openedAt).map(x=>x.topicId);items=ids.map(id=>state.topics.find(x=>x.id===id)).filter(Boolean).slice(0,50)}else if(kind==='trash')items=[...state.courses,...state.lessons,...state.topics].filter(x=>x.deletedAt);const title=kind==='favorites'?'Избранное':kind==='recent'?'Недавние':'Корзина';return shell(title,title,items.length?`<div class="list">${items.map(x=>`<div class="list-row"><div>•</div><div><div class="row-title">${esc(x.title)}</div><div class="row-sub">${x.deletedAt?'Удалено '+fmtDate(x.deletedAt):''}</div></div><div>${x.documentId?`<button class="btn" data-go="/topic/${x.id}">Открыть</button>`:''}${kind==='trash'?` <button class="btn" data-action="restore" data-id="${x.id}">Восстановить</button>`:''}</div></div>`).join('')}</div>`:`<div class="empty">Здесь пока ничего нет.</div>`) }
function renderSettings(){const s=state.settings;return shell('Настройки','Оформление · данные · хранилище',`<div class="settings-grid"><div class="setting-card"><h3>Оформление</h3><div class="field"><label>Режим</label><select class="select" id="mode-select"><option value="system">Системный</option><option value="dark">Тёмный</option><option value="light">Светлый</option></select></div><div class="section-head"><h2>20 визуальных тем</h2></div><div class="theme-grid">${THEME_NAMES.map(n=>{const t=THEMES[n];return `<button class="theme-card ${s.theme===n?'active':''}" data-theme="${n}" style="background:linear-gradient(135deg,${t[1]},${t[2]});color:${t[3]}"><span>${n}</span><small>${t[5]} · ${t[6]}</small></button>`}).join('')}</div></div><div class="setting-card"><h3>Чтение</h3><div class="field"><label>Размер текста: <span id="fs-val">${s.fontSize}</span> px</label><input id="font-size" type="range" min="14" max="24" value="${s.fontSize}"></div><div class="field"><label>Межстрочный интервал</label><input id="line-height" type="range" min="1.35" max="2.1" step=".05" value="${s.lineHeight}"></div><div class="field"><label>Ширина текста</label><select id="reader-width" class="select"><option value="56ch">Узкая</option><option value="68ch">Комфортная</option><option value="80ch">Широкая</option><option value="100%">Полная</option></select></div><div class="field"><label>Reader</label><select id="reader-theme" class="select"><option value="follow">Следовать приложению</option><option value="paper">Paper Light</option><option value="sepia">Sepia Book</option><option value="oled">OLED Black</option></select></div><div class="field"><label>Плотность интерфейса</label><select id="ui-density" class="select"><option value="compact">Компактная</option><option value="comfortable">Комфортная</option><option value="spacious">Просторная</option></select></div><div class="field"><label>Скругление карточек: <span id="radius-val">${s.cardRadius||20}</span> px</label><input id="card-radius" type="range" min="8" max="32" value="${s.cardRadius||20}"></div><div class="field"><label>Свечение: <span id="glow-val">${Math.round((s.glow??1)*100)}</span>%</label><input id="glow" type="range" min="0" max="1.8" step=".1" value="${s.glow??1}"></div><div class="toggle-row"><span>Уменьшить движение</span><button class="switch ${s.reducedMotion?'on':''}" data-action="toggle-motion" aria-pressed="${!!s.reducedMotion}"></button></div></div><div class="setting-card"><h3>Хранилище</h3><div id="storage-info" class="muted">Проверка…</div><div class="storage-meter" style="margin:12px 0"><span id="storage-bar"></span></div><button class="btn" data-action="persist">Защитить хранилище</button></div><div class="setting-card"><h3>Резервные копии</h3><p class="muted">Полная копия включает структуру, заметки, настройки и оригинальные PDF.</p><button class="btn primary" data-action="backup">Экспорт backup</button> <button class="btn" data-action="restore-backup">Импорт backup</button></div><div class="setting-card"><h3>Диагностика</h3><p>Версия: <b>${APP_VERSION}</b></p><p>База данных: schema 4</p><p>PDF engine: PDF.js 6.3.289 · local</p><button class="btn" data-action="demo">Добавить демонстрационный курс</button></div></div>`) }
function notFound(){return shell('Не найдено','',`<div class="empty"><h2>Элемент не найден</h2><button class="btn" data-go="/library">В библиотеку</button></div>`) }
function sorter(a,b){return (a.sortKey||'').localeCompare(b.sortKey||'')}
function render(){let html;if(state.route==='library')html=renderLibrary();else if(state.route==='course')html=renderCourse(state.params.id);else if(state.route==='lesson')html=renderLesson(state.params.id);else if(state.route==='topic')html=renderTopic(state.params.id);else if(state.route==='edit')html=renderEditor(state.params.id);else if(state.route==='search')html=renderSearch();else if(state.route==='pdf')html=renderPdf();else if(['favorites','recent','trash'].includes(state.route))html=renderSimpleList(state.route);else if(state.route==='settings')html=renderSettings();else html=notFound();app.innerHTML=html;afterRender()}
function afterRender(){document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el.dataset));if(state.route==='edit')setupEditor();if(state.route==='search')setupSearch();if(state.route==='settings')setupSettings();if(state.route==='pdf')setupPdfDrop();setupDragLists();document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:'smooth'})})}
function modal(title,html,buttons=''){const w=document.createElement('div');w.className='modal-backdrop';w.innerHTML=`<div class="modal"><h2>${esc(title)}</h2>${html}<div class="modal-actions">${buttons||'<button class="btn" data-close>Закрыть</button>'}</div></div>`;document.body.append(w);w.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>w.remove());return w}
async function action(a,d){if(a==='new-course'||a==='edit-course')editCourse(d.id);else if(a==='new-lesson'||a==='edit-lesson')editLesson(d.id);else if(a==='new-topic')editTopic(null,d.id);else if(a==='topic-menu')topicMenu(d.id);else if(a==='favorite'){const t=state.topics.find(x=>x.id===d.id);t.favorite=!t.favorite;t.updatedAt=DB.now();await DB.put('topics',t);render()}else if(a==='focus'){document.body.classList.add('focus-mode');const b=document.createElement('button');b.className='btn focus-exit';b.textContent='Выйти из фокуса';b.onclick=()=>{document.body.classList.remove('focus-mode');b.remove()};document.body.append(b)}else if(a==='search')doSearch();else if(a==='pick-pdf')pickPdf();else if(a==='persist'){const ok=await navigator.storage?.persist?.();toast(ok?'Постоянное хранилище разрешено':'Браузер не подтвердил постоянное хранилище');storageInfo()}else if(a==='backup')backup();else if(a==='restore-backup')restoreBackup();else if(a==='toggle-motion'){state.settings.reducedMotion=!state.settings.reducedMotion;await saveAppearance();render()}else if(a==='save-now')await saveEditorNow();else if(a==='source')openSource(d.source,Number(d.page||0));else if(a==='restore')restoreItem(d.id);else if(a==='demo')addDemo()}
function editCourse(id){const c=id?state.courses.find(x=>x.id===id):null;const w=modal(c?'Настроить курс':'Новый курс',`<div class="field"><label>Название</label><input id="m-title" class="input" value="${esc(c?.title||'')}"></div><div class="field"><label>Описание</label><textarea id="m-desc" class="textarea">${esc(c?.description||'')}</textarea></div><div class="field"><label>Иконка</label><input id="m-icon" class="input" value="${esc(c?.icon||'◈')}"></div>`,`<button class="btn" data-close>Отмена</button>${c?'<button class="btn danger" id="m-delete">В корзину</button>':''}<button class="btn primary" id="m-save">Сохранить</button>`);w.querySelector('#m-save').onclick=async()=>{const v={...(c||{}),id:c?.id||DB.uid('course'),title:w.querySelector('#m-title').value.trim()||'Без названия',description:w.querySelector('#m-desc').value.trim(),icon:w.querySelector('#m-icon').value.trim()||'◈',sortKey:c?.sortKey||String(Date.now()),createdAt:c?.createdAt||DB.now(),updatedAt:DB.now()};await DB.put('courses',v);await reloadData();w.remove();go('/course/'+v.id)};if(c)w.querySelector('#m-delete').onclick=()=>trashEntity('courses',c,w)}
function editLesson(idOrCourse){const existing=state.lessons.find(x=>x.id===idOrCourse);const courseId=existing?existing.courseId:idOrCourse;const w=modal(existing?'Настроить урок':'Новый урок',`<div class="field"><label>Название</label><input id="m-title" class="input" value="${esc(existing?.title||'')}"></div><div class="field"><label>Описание</label><textarea id="m-desc" class="textarea">${esc(existing?.description||'')}</textarea></div>`,`<button class="btn" data-close>Отмена</button>${existing?'<button class="btn danger" id="m-delete">В корзину</button>':''}<button class="btn primary" id="m-save">Сохранить</button>`);w.querySelector('#m-save').onclick=async()=>{const v={...(existing||{}),id:existing?.id||DB.uid('lesson'),courseId,title:w.querySelector('#m-title').value.trim()||'Без названия',description:w.querySelector('#m-desc').value.trim(),sortKey:existing?.sortKey||String(Date.now()),createdAt:existing?.createdAt||DB.now(),updatedAt:DB.now()};await DB.put('lessons',v);await reloadData();w.remove();go('/lesson/'+v.id)};if(existing)w.querySelector('#m-delete').onclick=()=>trashEntity('lessons',existing,w)}
function editTopic(tid,lessonId){const t=tid&&state.topics.find(x=>x.id===tid);const w=modal(t?'Настроить тему':'Новая тема',`<div class="field"><label>Название</label><input id="m-title" class="input" value="${esc(t?.title||'')}"></div><div class="field"><label>Подзаголовок</label><input id="m-sub" class="input" value="${esc(t?.subtitle||'')}"></div>`,`<button class="btn" data-close>Отмена</button><button class="btn primary" id="m-save">Сохранить</button>`);w.querySelector('#m-save').onclick=async()=>{const docId=t?.documentId||DB.uid('doc');const v={...(t||{}),id:t?.id||DB.uid('topic'),lessonId:t?.lessonId||lessonId,title:w.querySelector('#m-title').value.trim()||'Без названия',subtitle:w.querySelector('#m-sub').value.trim(),documentId:docId,favorite:t?.favorite||false,sortKey:t?.sortKey||String(Date.now()),createdAt:t?.createdAt||DB.now(),updatedAt:DB.now()};await DB.put('topics',v);if(!t)await DB.put('documents',{id:docId,topicId:v.id,schemaVersion:1,blocks:[],revision:1,plainText:'',createdAt:DB.now(),updatedAt:DB.now()});await reloadData();w.remove();go('/edit/'+v.id)}}
function topicMenu(id){const t=state.topics.find(x=>x.id===id);const w=modal(t.title,`<div class="list"><button class="btn" id="edit">Переименовать</button><button class="btn" id="dup">Дублировать</button><button class="btn" id="fav">${t.favorite?'Убрать из избранного':'В избранное'}</button><button class="btn danger" id="del">В корзину</button></div>`);w.querySelector('#edit').onclick=()=>{w.remove();editTopic(id)};w.querySelector('#fav').onclick=async()=>{t.favorite=!t.favorite;await DB.put('topics',t);await reloadData();w.remove();render()};w.querySelector('#dup').onclick=async()=>{const d=state.documents.find(x=>x.id===t.documentId),nid=DB.uid('topic'),ndid=DB.uid('doc');await DB.put('topics',{...structuredClone(t),id:nid,documentId:ndid,title:t.title+' — копия',sortKey:String(Date.now()),createdAt:DB.now(),updatedAt:DB.now()});await DB.put('documents',{...structuredClone(d),id:ndid,topicId:nid,blocks:(d?.blocks||[]).map(b=>({...b,id:crypto.randomUUID()})),createdAt:DB.now(),updatedAt:DB.now()});await reloadData();w.remove();render()};w.querySelector('#del').onclick=()=>trashEntity('topics',t,w)}
async function trashEntity(store,obj,w){obj.deletedAt=DB.now();await DB.put(store,obj);await DB.put('trash',{id:obj.id,store,deletedAt:obj.deletedAt});await reloadData();w.remove();toast('Перемещено в корзину');go('/library')}
async function restoreItem(id){for(const [store,arr] of [['courses',state.courses],['lessons',state.lessons],['topics',state.topics]]){const x=arr.find(v=>v.id===id);if(x){delete x.deletedAt;await DB.put(store,x);break}}await DB.del('trash',id);await reloadData();render();toast('Восстановлено')}
let editorSaveTimer;
function setupEditor(){const blocksEl=document.querySelector('#blocks'),tid=state.params.id,t=state.topics.find(x=>x.id===tid),d=state.documents.find(x=>x.id===t.documentId);document.querySelector('#topic-title').oninput=()=>markDirty();document.querySelectorAll('[data-addtype]').forEach(b=>b.onclick=()=>addBlock(b.dataset.addtype));blocksEl.addEventListener('input',()=>markDirty());blocksEl.querySelectorAll('[data-delblock]').forEach(b=>b.onclick=()=>{d.blocks=d.blocks.filter(x=>x.id!==b.dataset.delblock);markDirty();render()});blocksEl.querySelectorAll('[data-pickimage]').forEach(b=>b.onclick=()=>pickImageForBlock(b.dataset.pickimage));setupBlockDrag(blocksEl,d)}
function pickImageForBlock(blockId){const t=state.topics.find(x=>x.id===state.params.id),d=state.documents.find(x=>x.id===t.documentId),b=d.blocks.find(x=>x.id===blockId);if(!b)return;picker.accept='image/*';picker.onchange=()=>{const f=picker.files[0];picker.value='';if(!f)return;if(f.size>8*1024*1024)return toast('Изображение слишком большое · максимум 8 МБ');const r=new FileReader();r.onload=()=>{b.src=String(r.result||'');markDirty();render()};r.readAsDataURL(f)};picker.click()}
function addBlock(type){const t=state.topics.find(x=>x.id===state.params.id),d=state.documents.find(x=>x.id===t.documentId);let b={id:crypto.randomUUID(),type,text:''};if(type.startsWith('callout:')){b.type='callout';b.kind=type.split(':')[1]}if(type==='table')b.rows=[['Заголовок 1','Заголовок 2'],['','']];d.blocks.push(b);markDirty();render();setTimeout(()=>document.querySelector('.block:last-of-type .block-input')?.focus(),20)}
function collectEditor(){const t=state.topics.find(x=>x.id===state.params.id),d=state.documents.find(x=>x.id===t.documentId);t.title=document.querySelector('#topic-title')?.value.trim()||t.title;document.querySelectorAll('[data-block]').forEach(el=>{const b=d.blocks.find(x=>x.id===el.dataset.block);if(!b)return;el.querySelectorAll('[data-field]').forEach(inp=>{if(inp.dataset.field==='rows')b.rows=inp.value.split('\n').map(r=>r.split('|').map(x=>x.trim()));else b[inp.dataset.field]=inp.value})});d.plainText=[t.title,...d.blocks.flatMap(b=>[b.text||'',...(b.rows||[]).flat()])].join('\n');d.updatedAt=t.updatedAt=DB.now();return {t,d}}
function markDirty(){state.dirty=true;const s=document.querySelector('#save-state');if(s)s.textContent='Сохранение…';clearTimeout(editorSaveTimer);editorSaveTimer=setTimeout(saveEditorNow,320)}
async function saveEditorNow(){if(state.route!=='edit')return;const {t,d}=collectEditor();await DB.put('topics',t);await DB.put('documents',d);state.dirty=false;const s=document.querySelector('#save-state');if(s)s.textContent='Сохранено';rebuildSearchSoon()}
function setupBlockDrag(el,d){let dragged=null;el.querySelectorAll('.block').forEach(b=>{b.ondragstart=()=>dragged=b.dataset.block;b.ondragover=e=>e.preventDefault();b.ondrop=()=>{if(!dragged||dragged===b.dataset.block)return;const from=d.blocks.findIndex(x=>x.id===dragged),to=d.blocks.findIndex(x=>x.id===b.dataset.block);const [x]=d.blocks.splice(from,1);d.blocks.splice(to,0,x);markDirty();render()}})}
function setupDragLists(){let drag=null;document.querySelectorAll('[data-drag]').forEach(el=>{el.ondragstart=()=>drag={id:el.dataset.id,type:el.dataset.drag};el.ondragover=e=>e.preventDefault();el.ondrop=async()=>{if(!drag||drag.type!==el.dataset.drag||drag.id===el.dataset.id)return;const arr=drag.type==='lesson'?state.lessons:state.topics;const relevant=arr.filter(x=>drag.type==='lesson'?x.courseId===arr.find(z=>z.id===drag.id)?.courseId:x.lessonId===arr.find(z=>z.id===drag.id)?.lessonId).filter(x=>!x.deletedAt).sort(sorter);const fi=relevant.findIndex(x=>x.id===drag.id),ti=relevant.findIndex(x=>x.id===el.dataset.id);const [x]=relevant.splice(fi,1);relevant.splice(ti,0,x);relevant.forEach((v,i)=>v.sortKey=String(i).padStart(6,'0'));await DB.bulkPut(drag.type==='lesson'?'lessons':'topics',relevant);await reloadData();render()}})}
let searchWorker;
async function rebuildSearch(){if(!searchWorker)searchWorker=new Worker('./search-worker.js');const docs=state.topics.filter(t=>!t.deletedAt).map(t=>{const l=state.lessons.find(x=>x.id===t.lessonId),c=l&&state.courses.find(x=>x.id===l.courseId),d=state.documents.find(x=>x.id===t.documentId);return {id:t.id,title:t.title,lesson:l?.title||'',course:c?.title||'',body:d?.plainText||''}});searchWorker.postMessage({type:'INDEX',payload:docs})}
let rsTimer;function rebuildSearchSoon(){clearTimeout(rsTimer);rsTimer=setTimeout(rebuildSearch,500)}
function setupSearch(){rebuildSearch();const i=document.querySelector('#search-input');i.onkeydown=e=>{if(e.key==='Enter')doSearch()};setTimeout(()=>i.focus(),50)}
async function doSearch(){const q=document.querySelector('#search-input')?.value||'';if(!searchWorker)await rebuildSearch();searchWorker.onmessage=e=>{if(e.data.type==='RESULTS'){state.searchResults=e.data.results;const r=document.querySelector('#search-results');if(r)r.innerHTML=searchResultsHtml();afterRenderSearch()}};searchWorker.postMessage({type:'SEARCH',payload:q})}
function afterRenderSearch(){document.querySelectorAll('#search-results [data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go))}
function setupSettings(){const mode=document.querySelector('#mode-select');mode.value=state.settings.mode;mode.onchange=async()=>{state.settings.mode=mode.value;await saveAppearance();applyTheme();render()};const w=document.querySelector('#reader-width');w.value=state.settings.width;w.onchange=async()=>{state.settings.width=w.value;await saveAppearance();applyTheme()};const rt=document.querySelector('#reader-theme');rt.value=state.settings.readerTheme;rt.onchange=async()=>{state.settings.readerTheme=rt.value;await saveAppearance();applyTheme()};const den=document.querySelector('#ui-density');den.value=state.settings.uiDensity||'comfortable';den.onchange=async()=>{state.settings.uiDensity=den.value;await saveAppearance();applyTheme()};const rad=document.querySelector('#card-radius');rad.oninput=()=>{state.settings.cardRadius=Number(rad.value);document.querySelector('#radius-val').textContent=rad.value;applyTheme()};rad.onchange=saveAppearance;const glow=document.querySelector('#glow');glow.oninput=()=>{state.settings.glow=Number(glow.value);document.querySelector('#glow-val').textContent=Math.round(Number(glow.value)*100);applyTheme()};glow.onchange=saveAppearance;const fs=document.querySelector('#font-size');fs.oninput=()=>{state.settings.fontSize=Number(fs.value);document.querySelector('#fs-val').textContent=fs.value;applyTheme()};fs.onchange=saveAppearance;const lh=document.querySelector('#line-height');lh.oninput=()=>{state.settings.lineHeight=Number(lh.value);applyTheme()};lh.onchange=saveAppearance;document.querySelectorAll('[data-theme]').forEach(x=>x.onclick=async()=>{state.settings.theme=x.dataset.theme;await saveAppearance();applyTheme();render()});storageInfo()}
async function saveAppearance(){await DB.setSetting('appearance',state.settings)}
async function storageInfo(){const est=await navigator.storage?.estimate?.();const persisted=await navigator.storage?.persisted?.();const e=document.querySelector('#storage-info'),b=document.querySelector('#storage-bar');if(e&&est){const mb=n=>(n/1048576).toFixed(1);e.textContent=`Использовано ${mb(est.usage||0)} МБ из ориентировочно ${mb(est.quota||0)} МБ · persistent: ${persisted?'да':'нет'}`;if(b)b.style.width=Math.min(100,(est.usage||0)/(est.quota||1)*100)+'%'}}
function setupPdfDrop(){const d=document.querySelector('#pdf-drop');d.ondragover=e=>{e.preventDefault();d.classList.add('dragover')};d.ondragleave=()=>d.classList.remove('dragover');d.ondrop=e=>{e.preventDefault();d.classList.remove('dragover');const f=e.dataTransfer.files[0];if(f)importPdf(f)}}
function pickPdf(){picker.accept='application/pdf,.pdf';picker.onchange=()=>{const f=picker.files[0];if(f)importPdf(f);picker.value=''};picker.click()}
async function importPdf(file){if(file.type&&file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))return toast('Выберите PDF');const est=await navigator.storage?.estimate?.();if(est&&est.quota-est.usage<file.size*1.6)return toast('Недостаточно локального места');document.querySelector('#pdf-progress')?.classList.remove('hidden');document.querySelector('#pdf-name').textContent=file.name;const bar=document.querySelector('#pdf-bar'),status=document.querySelector('#pdf-status');const sourceId=DB.uid('pdf'),assetId=DB.uid('asset');try{status.textContent='Сохраняю оригинал…';await DB.saveBlob(assetId,file);await DB.put('assets',{id:assetId,kind:'pdf',mime:'application/pdf',byteSize:file.size,status:'ready',createdAt:DB.now()});status.textContent='Анализирую текст…';const a=await analyzePdf(file,p=>{bar.style.width=Math.round(p*100)+'%'});const src={id:sourceId,assetId,originalFileName:file.name,pageCount:a.pageCount,importedAt:DB.now(),extractionVersion:2,extractionEngine:a.engine||'PDF.js',warnings:a.warnings};await DB.put('pdfSources',src);const w=modal('PDF проанализирован',`<p><b>${esc(file.name)}</b></p><p>${a.pageCount} стр. · извлечено ${a.text.length.toLocaleString('ru-RU')} символов</p>${a.warnings.map(x=>`<div class="warnbox" style="margin:8px 0">${esc(x)}</div>`).join('')}<div class="field"><label>Куда импортировать</label><select id="pdf-course" class="select"><option value="new">Создать новый курс</option>${state.courses.filter(x=>!x.deletedAt).map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Название курса/урока</label><input id="pdf-title" class="input" value="${esc(file.name.replace(/\.pdf$/i,''))}"></div>`,`<button class="btn" data-close>Оставить только оригинал</button><button class="btn primary" id="pdf-commit">Импортировать текст</button>`);w.querySelector('#pdf-commit').onclick=async()=>{await commitPdfImport(a,src,w.querySelector('#pdf-course').value,w.querySelector('#pdf-title').value||'PDF');w.remove();toast('PDF импортирован');go('/library')};await reloadData()}catch(e){console.error(e);status.textContent='Ошибка: '+e.message;toast('PDF сохранён не полностью: '+e.message)}}
async function commitPdfImport(a,src,courseChoice,title){let course;if(courseChoice==='new'){course={id:DB.uid('course'),title,description:`Импортировано из ${src.originalFileName}`,icon:'▣',sortKey:String(Date.now()),createdAt:DB.now(),updatedAt:DB.now()};await DB.put('courses',course)}else course=state.courses.find(x=>x.id===courseChoice);const lesson={id:DB.uid('lesson'),courseId:course.id,title:'Импорт PDF',description:src.originalFileName,sortKey:String(Date.now()),createdAt:DB.now(),updatedAt:DB.now()};await DB.put('lessons',lesson);const blocks=textToBlocks(a,src.id);const chunkSize=120;for(let i=0;i<blocks.length;i+=chunkSize){const chunk=blocks.slice(i,i+chunkSize),topicId=DB.uid('topic'),docId=DB.uid('doc');const topic={id:topicId,lessonId:lesson.id,title:chunk.find(x=>x.type==='heading')?.text||`${title} · часть ${Math.floor(i/chunkSize)+1}`,subtitle:`Источник: ${src.originalFileName}`,documentId:docId,favorite:false,sortKey:String(i).padStart(6,'0'),createdAt:DB.now(),updatedAt:DB.now()};const doc={id:docId,topicId,schemaVersion:1,blocks:chunk,plainText:chunk.map(x=>x.text).join('\n'),revision:1,createdAt:DB.now(),updatedAt:DB.now()};await DB.put('topics',topic);await DB.put('documents',doc);for(const b of chunk.filter(x=>x.source))await DB.put('sourceAnchors',{id:DB.uid('anchor'),sourceId:src.id,topicId,blockId:b.id,pageIndex:b.source.pageIndex||0,rects:b.source.rects||[],importedTextHash:''})}await reloadData();await rebuildSearch()}
async function openSource(sourceId,page=0){const s=state.pdfSources.find(x=>x.id===sourceId);if(!s)return toast('Источник не найден');const blob=await DB.loadBlob(s.assetId);if(!blob)return toast('Файл источника отсутствует');const url=URL.createObjectURL(blob);const w=modal('Источник PDF',`<div class="source-meta">${esc(s.originalFileName)} · ориентир: страница ${page+1}</div><iframe class="source-frame" src="${url}#page=${page+1}"></iframe>`);w.addEventListener('remove',()=>URL.revokeObjectURL(url))}
async function backup(){toast('Формирую backup…');const data=await DB.exportRaw(),entries=[];entries.push({name:'manifest.json',data:new Blob([JSON.stringify({format:'knowledge-studio-backup',backupFormatVersion:1,schemaVersion:4,createdAt:new Date().toISOString(),appVersion:APP_VERSION})])});entries.push({name:'data/library.json',data:new Blob([JSON.stringify(data)])});for(const s of state.pdfSources){const b=await DB.loadBlob(s.assetId);if(b)entries.push({name:`assets/pdf/${s.assetId}.pdf`,data:b})}const zip=await makeZip(entries),a=document.createElement('a');a.href=URL.createObjectURL(zip);a.download=`knowledge-studio-${new Date().toISOString().slice(0,10)}.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Backup готов')}
function restoreBackup(){picker.accept='.zip,application/zip';picker.onchange=async()=>{const f=picker.files[0];picker.value='';if(!f)return;try{const files=await readZip(f);if(!files['manifest.json']||!files['data/library.json'])throw new Error('Неверный формат backup');const man=JSON.parse(new TextDecoder().decode(files['manifest.json']));if(man.format!=='knowledge-studio-backup')throw new Error('Неизвестный backup');const data=JSON.parse(new TextDecoder().decode(files['data/library.json']));const w=modal('Восстановить backup?',`<div class="warnbox">Текущие данные будут заменены только после успешной проверки структуры. Перед восстановлением рекомендуется сохранить свежий backup.</div><p>Дата: ${esc(man.createdAt||'')}</p>`,`<button class="btn" data-close>Отмена</button><button class="btn danger" id="restore-confirm">Восстановить</button>`);w.querySelector('#restore-confirm').onclick=async()=>{await applyRestore(data,files);w.remove();toast('Backup восстановлен');go('/library')}}catch(e){toast('Backup отклонён: '+e.message)}};picker.click()}
async function applyRestore(data,files){const names=['courses','lessons','topics','documents','pdfSources','sourceAnchors','favorites','recent','trash','settings','revisions'];for(const n of names){await DB.clear(n);await DB.bulkPut(n,data[n]||[])}for(const src of data.pdfSources||[]){const u=files[`assets/pdf/${src.assetId}.pdf`];if(u)await DB.saveBlob(src.assetId,new Blob([u],{type:'application/pdf'}))}await reloadData();state.settings={...state.settings,...await DB.setting('appearance',{})};applyTheme()}
async function touchRecent(t){if(!t||state._touching===t.id)return;state._touching=t.id;const old=state.recent.find(x=>x.topicId===t.id),r=old||{id:DB.uid('recent'),topicId:t.id};r.openedAt=DB.now();await DB.put('recent',r);setTimeout(()=>state._touching=null,200)}
async function reloadData(){state.courses=await DB.all('courses');state.lessons=await DB.all('lessons');state.topics=await DB.all('topics');state.documents=await DB.all('documents');state.pdfSources=await DB.all('pdfSources');state.sourceAnchors=await DB.all('sourceAnchors');state.recent=await DB.all('recent')}
async function addDemo(){if(state.courses.some(c=>c.title==='DeFi — демонстрация'))return toast('Демо уже существует');const c={id:DB.uid('course'),title:'DeFi — демонстрация',description:'Пример красивого учебного курса Knowledge Studio',icon:'⬡',sortKey:'000001',createdAt:DB.now(),updatedAt:DB.now()};const l={id:DB.uid('lesson'),courseId:c.id,title:'Основы Ethereum',description:'Структурированный учебный материал',sortKey:'000001',createdAt:DB.now(),updatedAt:DB.now()};const tid=DB.uid('topic'),did=DB.uid('doc');const t={id:tid,lessonId:l.id,title:'Ethereum State',subtitle:'Как сеть хранит текущее состояние',documentId:did,favorite:true,sortKey:'000001',createdAt:DB.now(),updatedAt:DB.now()};const blocks=[{id:crypto.randomUUID(),type:'paragraph',text:'Ethereum можно рассматривать как систему переходов между состояниями. Каждая корректная транзакция изменяет часть текущего состояния сети.'},{id:crypto.randomUUID(),type:'callout',kind:'keyIdea',text:'Blockchain хранит историю переходов, а state — результат применения этих переходов к текущему моменту.'},{id:crypto.randomUUID(),type:'heading',text:'Что находится в state?'},{id:crypto.randomUUID(),type:'callout',kind:'definition',text:'Состояние включает аккаунты, балансы, nonce, код контрактов и их storage.'},{id:crypto.randomUUID(),type:'heading3',text:'Пример структуры'},{id:crypto.randomUUID(),type:'table',rows:[['Поле','Смысл'],['Balance','Количество ETH'],['Nonce','Счётчик операций'],['Storage','Данные контракта']]},{id:crypto.randomUUID(),type:'callout',kind:'question',text:'Почему история блокчейна и текущее состояние — не одно и то же?'}];const doc={id:did,topicId:tid,schemaVersion:1,blocks,plainText:blocks.map(b=>b.text||'').join('\n'),revision:1,createdAt:DB.now(),updatedAt:DB.now()};await DB.bulkPut('courses',[c]);await DB.bulkPut('lessons',[l]);await DB.bulkPut('topics',[t]);await DB.bulkPut('documents',[doc]);await reloadData();toast('Демонстрационный курс добавлен');go('/course/'+c.id)}
function setupSW(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn)}
addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state.route==='edit'&&state.dirty)saveEditorNow()});
load().catch(e=>{console.error(e);app.innerHTML=`<div style="padding:30px"><h1>Knowledge Studio</h1><p>Ошибка запуска: ${esc(e.message)}</p></div>`});
